const statuses = new Set<ReservationStatus>(["held", "confirmed", "cancelled"]);

function requireText(value: string, name: string): void {
  if (typeof value !== "string" || value.length === 0) {
    throw new TypeError(`${name} must be a non-empty string`);
  }
}

function validateReservation(value: Reservation): void {
  if (typeof value !== "object" || value === null) {
    throw new TypeError("Invalid reservation");
  }
  requireText(value.id, "id");
  requireText(value.owner, "owner");
  if (!Number.isInteger(value.seats) || value.seats <= 0 || !statuses.has(value.status)) {
    throw new TypeError("Invalid reservation");
  }
}

export class ReservationStore {
  private readonly records = new Map<string, Reservation>();

  constructor(initial: readonly Reservation[] = []) {
    for (const reservation of initial) {
      this.add(reservation);
    }
  }

  add(reservation: Reservation): void {
    validateReservation(reservation);
    if (this.records.has(reservation.id)) {
      throw new Error(`Duplicate reservation: ${reservation.id}`);
    }
    this.records.set(reservation.id, { ...reservation });
  }

  listByOwner(owner: string): Reservation[] {
    requireText(owner, "owner");
    return [...this.records.values()]
      .filter((reservation) => reservation.owner === owner);
  }

