    const current = this.records.get(id);
    if (current === undefined) {
      throw new Error(`Unknown reservation: ${id}`);
    }
    const updated = { ...current, status };
    this.records.set(id, updated);
    return { ...updated };
  }

  remove(id: string): Reservation {
    requireText(id, "id");
    const current = this.records.get(id);
    if (current === undefined) {
      throw new Error(`Unknown reservation: ${id}`);
    }
    this.records.delete(id);
    return { ...current };
  }
