import { Reservation, ReservationStatus, ReservationStore } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function expectError(action: () => void, ctor: typeof Error, message: string): void {
  let caught: unknown;
  try { action(); } catch (error) { caught = error; }
  assert(caught instanceof ctor, message);
}

const empty = new ReservationStore();
assert(empty.listByOwner("nobody").length === 0, "empty store returns an empty list");

const initial: Reservation = { id: "r1", owner: "alice", seats: 2, status: "held" };
const store = new ReservationStore([initial]);
initial.owner = "mutated";
initial.seats = 99;
initial.status = "cancelled";
store.add({ id: "r2", owner: "bob", seats: 1, status: "confirmed" });
const third: Reservation = { id: "r3", owner: "alice", seats: 4, status: "held" };
store.add(third);
third.owner = "bob";

const alice1 = store.listByOwner("alice");
assert(alice1.length === 2 && alice1[0].id === "r1" && alice1[1].id === "r3", "owner listing preserves insertion order");
assert(alice1[0].seats === 2 && alice1[0].status === "held", "incoming records must be copied");
alice1[0].owner = "corrupted";
alice1[0].seats = 100;
const alice2 = store.listByOwner("alice");
assert(alice2 !== alice1 && alice2[0] !== alice1[0], "list results must be fresh copies");
assert(alice2[0].owner === "alice" && alice2[0].seats === 2, "returned records must not alias stored state");

const changed = store.changeStatus("r1", "confirmed");
assert(changed.status === "confirmed", "changeStatus returns updated status");
changed.status = "cancelled";
assert(store.listByOwner("alice")[0].status === "confirmed", "changeStatus result must be a fresh copy");
const removed = store.remove("r2");
assert(removed.id === "r2" && removed.status === "confirmed", "remove returns removed record");
removed.owner = "changed";
assert(store.listByOwner("bob").length === 0, "removed record must no longer be stored");

expectError(() => store.add({ id: "r1", owner: "other", seats: 1, status: "held" }), Error, "duplicate IDs throw Error");
expectError(() => store.changeStatus("unknown", "held"), Error, "unknown status-change ID throws Error");
expectError(() => store.remove("unknown"), Error, "unknown removal ID throws Error");
assert(store.listByOwner("alice").length === 2, "failed operations leave state unchanged");

const badReservations: unknown[] = [
  null,
  { id: "", owner: "a", seats: 1, status: "held" },
  { id: "x", owner: "", seats: 1, status: "held" },
  { id: "x", owner: "a", seats: 0, status: "held" },
  { id: "x", owner: "a", seats: -1, status: "held" },
  { id: "x", owner: "a", seats: 1.5, status: "held" },
  { id: "x", owner: "a", seats: 1, status: "pending" }
];
for (const bad of badReservations) {
  expectError(() => new ReservationStore([bad as Reservation]), TypeError, "malformed initial reservation throws TypeError");
  expectError(() => store.add(bad as Reservation), TypeError, "malformed added reservation throws TypeError");
}
expectError(() => store.listByOwner(""), TypeError, "empty owner argument throws TypeError");
expectError(() => store.listByOwner(3 as unknown as string), TypeError, "non-string owner throws TypeError");
expectError(() => store.changeStatus("", "held"), TypeError, "empty ID throws TypeError");
expectError(() => store.changeStatus("r1", "bad" as ReservationStatus), TypeError, "invalid status throws TypeError");
expectError(() => store.remove(4 as unknown as string), TypeError, "non-string removal ID throws TypeError");

